const input = Array.isArray($json) ? $json : [$json];
const eligible = [];
let skippedNoOptIn = 0;
for (const customer of input) {
  if (!customer.optInSource) {
    skippedNoOptIn += 1;
    continue;
  }
  const heaterAgeYears = Number(`${customer.waterHeaterAge ?? '0'}`.replace(/\D/g, ''));
  const monthsSinceDrain = Number(customer.monthsSinceLastDrainService ?? 0);
  let segment;
  if (heaterAgeYears >= 8) segment = 'water-heater-replacement-watch';
  else if (monthsSinceDrain >= 12) segment = 'drain-service-due';
  else segment = 'no-campaign-this-cycle';
  const nextAction = segment === 'water-heater-replacement-watch'
    ? 'Send approved water-heater aging check-in.'
    : segment === 'drain-service-due'
      ? 'Send approved drain-service cadence reminder.'
      : 'No outreach this cycle.';
  eligible.push({ json: { ...customer, segment, nextAction } });
}
eligible.push({ json: { reactivationSummary: true, eligibleCount: eligible.length, skippedNoOptIn, gate: 'Records without optInSource are excluded. FCC one-to-one consent: consent is not shared across brands or bought as leads, and no purchased lists enter this flow.' } });
return eligible;
